69	    @Test
70	    void cannotGreedilyTakeHighestVersionAcrossMultipleLevels() {
71	        // app -> a[1,2]；a2 -> b[2,2]，a1 -> b[1,1]；b2 已撤回，b1 有效。
72	        // 贪心取 a2 将失败，必须回退到 a1/b1。
73	        RepositorySnapshot s = snapshot(0,
74	                "app", List.of(v(1, dep("a", 1, 2))),
75	                "a", List.of(v(2, dep("b", 2, 2)), v(1, dep("b", 1, 1))),
76	                "b", List.of(w(2), v(1)));
77	
78	        assertThat(LockResolver.resolve(s, "app", 1))
79	                .isEqualTo(Map.of("app", 1, "a", 1, "b", 1));
80	    }
81	
82	    @Test
83	    void detectsUnsatisfiableCycleAndReturnsNull() {
84	        // 根 app:1 固定，a1 -> app[2,2]，但 app 只能是 1，环冲突不可行。
85	        RepositorySnapshot s = snapshot(0,
86	                "app", List.of(v(1, dep("a", 1, 1)), v(2)),
87	                "a", List.of(v(1, dep("app", 2, 2))));
88	
89	        assertThat(LockResolver.resolve(s, "app", 1)).isNull();
90	    }
91	
92	    @Test
93	    void supportsConsistentCycle() {
94	        // app:1 -> a[1,1]，a1 -> app[1,1]：环但区间互相满足。
95	        RepositorySnapshot s = snapshot(0,
96	                "app", List.of(v(1, dep("a", 1, 1)), v(2, dep("a", 1, 1))),
97	                "a", List.of(v(1, dep("app", 1, 1))));
98	
99	        assertThat(LockResolver.resolve(s, "app", 1))
100	                .isEqualTo(Map.of("app", 1, "a", 1));
101	    }
102	
103	    @Test
104	    void selfDependencyMustMatchFixedRootVersion() {
105	        RepositorySnapshot s = snapshot(0,
106	                "app", List.of(v(2, dep("app", 2, 2)), v(1, dep("app", 1, 1))));
107	        assertThat(LockResolver.resolve(s, "app", 1)).isEqualTo(Map.of("app", 1));
108	        assertThat(LockResolver.resolve(s, "app", 2)).isEqualTo(Map.of("app", 2));
109	    }
110	
111	    @Test
112	    void selfDependencyMismatchIsInfeasible() {
113	        RepositorySnapshot s = snapshot(0,
114	                "app", List.of(v(1, dep("app", 2, 2)), v(2)));
115	        assertThat(LockResolver.resolve(s, "app", 1)).isNull();
116	    }
117	
