        assertThat(diffs).hasSize(1);
        ReresolveDiffer.Diff d = diffs.get(0);
        assertThat(d.name()).isEqualTo("lib");
        assertThat(d.changeType()).isEqualTo(ReresolveDiffer.VERSION_CHANGED);
        assertThat(d.originalVersion()).isEqualTo(1);
