    void downgradeBecauseOldVersionRequiresMissingDependencyIsRangeChange() {
        // 原锁定 lib2，它现在依赖 newdep[1,1]（可行解中无法满足：newdep 不存在），
        // 可行解回退 lib1。注意：实际可行解不会包含 newdep。
